import{_ as r,C as i,o as d,c as l,j as a,a as o,E as n,a2 as s}from"./chunks/framework.B-bxTAy7.js";const b=JSON.parse('{"title":"这个站是什么","description":"速通 Wiki 的定位、内容范围与使用方式：四门电学课的学习笔记，结论先行、可交互演示、可查可溯源。","frontmatter":{"title":"这个站是什么","description":"速通 Wiki 的定位、内容范围与使用方式：四门电学课的学习笔记，结论先行、可交互演示、可查可溯源。"},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1792474335000}'),h={name:"guide/index.md"};function c(f,t,g,u,p,_){const e=i("Meta");return d(),l("div",null,[t[0]||(t[0]=a("h1",{id:"这个站是什么",tabindex:"-1"},[o("这个站是什么 "),a("a",{class:"header-anchor",href:"#这个站是什么","aria-label":'Permalink to "这个站是什么"'},"​")],-1)),n(e,{time:"3 min",level:"指南",note:"先弄清楚它是什么，再决定怎么读"}),t[1]||(t[1]=s('<p>这是一个<strong>个人维护的电学学习 Wiki</strong>：四门课（电工学、数字电路、模拟电子、嵌入式开发）的正文、公式、图解和可交互演示放在同一个站里，互相链接、按课程组织。</p><p>它不是教材的电子版，也不是题库。它解决的是三个具体问题：</p><ol><li><strong>时间有限时，先读什么</strong> —— 每节都标了「核心 / 了解 / 可跳过」和预计耗时，课程主页给了速通、系统、补强三条路径。</li><li><strong>看不懂的前置知识，不用跳走</strong> —— 正文里的胶囊按钮点开就是一张前置知识卡片，读完按 <kbd>Esc</kbd> 回到原处。</li><li><strong>结论记不住，想验证</strong> —— 46 处可拖参数的 DemoBox 演示（背后是 43 个仿真组件），把公式变成能自己动的东西。</li></ol><h2 id="内容范围" tabindex="-1">内容范围 <a class="header-anchor" href="#内容范围" aria-label="Permalink to &quot;内容范围&quot;">​</a></h2><table tabindex="0"><thead><tr><th>课程</th><th>章节数</th><th>定位</th></tr></thead><tbody><tr><td><a href="./../ee/">电工学</a></td><td>22 节 + 3 节数电速览</td><td>强电与工程视角的主线</td></tr><tr><td><a href="./../digital/">数字电路</a></td><td>8 节</td><td>从数制到 AD/DA 的离散逻辑</td></tr><tr><td><a href="./../analog/">模拟电子</a></td><td>9 节</td><td>从器件到直流电源的连续信号</td></tr><tr><td><a href="./../embedded/">嵌入式开发</a></td><td>12 节</td><td>STM32 外设与 RTOS</td></tr></tbody></table><p>除此之外还有三类工具页：</p><ul><li><a href="./../shared/cheatsheet">公式速查表</a>：全部公式、单位、符号约定，考前扫一遍；</li><li><a href="./../ee/graph">知识依赖图谱</a>：哪一章依赖哪一章，用来排顺序；</li><li><a href="./status">内容状态与成熟度</a>：由构建脚本扫描正文生成，直白写出每节写到什么程度。</li></ul><h2 id="写作原则" tabindex="-1">写作原则 <a class="header-anchor" href="#写作原则" aria-label="Permalink to &quot;写作原则&quot;">​</a></h2><ul><li><strong>结论先行</strong>：每页开头先给能直接用的结论，推导只放在理解必需的地方。</li><li><strong>数字要能验算</strong>：例题里的数值都自己算过；能画图的不用文字描述。</li><li><strong>不装作完整</strong>：没写透的章节会在<a href="./status">内容状态</a>里标出来，而不是用「敬请期待」糊过去。</li><li><strong>可溯源</strong>：内容基于秦曾煌《电工学》、康华光《电子技术基础》等教材整理，引用与勘误见<a href="./about">关于与版权</a>。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>第一次来：<a href="./start">怎么用这个站</a></li><li>想直接开读：<a href="./../ee/">电工学路线图</a></li><li>想参与修订：<a href="./contributing">写作与贡献指南</a></li></ul>',11))])}const x=r(h,[["render",c]]);export{b as __pageData,x as default};
